/** Salidas del paso: un writer por archivo, escritos en el mismo recorrido de B02TMOVTOS. */
@Configuration
public class TeletonFiles {

    @Bean @StepScope
    FlatFileItemWriter<S244Record> movs244(@Value("#{jobParameters['fechaLinea']}") String f) {
        return new FlatFileItemWriterBuilder<S244Record>()
                .name("I04-MOVS244").resource(salida("s244", f))     // 100 bytes
                .lineAggregator(S244Record::linea).build();
    }

    @Bean @StepScope
    FlatFileItemWriter<PunteoRecord> punteo151(@Value("#{jobParameters['fechaLinea']}") String f) {
        return new FlatFileItemWriterBuilder<PunteoRecord>()
                .name("I08-PUNTEOS151").resource(salida("punteo151", f))   // 48 bytes
                .lineAggregator(PunteoRecord::linea).build();
    }

    @Bean @StepScope
    FlatFileItemWriter<AmexRecord> amexMn(@Value("#{jobParameters['fechaLinea']}") String f) {
