  transferencia:
    llave: "S501T01"                       # WKS-TX940-LLAVE (línea 1305)
    wfl: "(S006)S006/WFL/P940/01MTP001"
  # La credencial del ambiente de pruebas ya no vive en el código:
  # se inyecta desde el gestor de secretos y solo en el perfil de pruebas.

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class TransferenciaP940 {

    private final TransferenciaProperties props;
    private final MftClient mft;                 // transferencia gestionada en lugar de BEGIN JOB ... START P940
    private final SecretProvider secretos;       // Vault / Key Vault / Secrets Manager

    public void transfiere(LocalDate fechaLinea, String host) {
        Optional<Credencial> cred = host.startsWith("ACYPBETA")
                ? Optional.of(secretos.credencial("p630.pruebas"))
                : Optional.empty();
        mft.envia(props.llave(), fechaLinea, cred);
    }
}

@Configuration
public class TeletonJobConfig {

    @Bean
    Job donativosTeleton(JobRepository repo, Step generaArchivos, Step transfiere, Step marcaPaso) {
        return new JobBuilder("S500P630", repo)
                .start(generaArchivos)     // 100-GENERA-ARCHIVO
                .next(transfiere)          // 999999-FIN: INTELAR + P940
                .next(marcaPaso)           // B00T-PASO-ENTRA / PASO-SALE = 630
                .build();
    }
}

